CREATE TABLE sales_order (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), store_id UUID NOT NULL REFERENCES store(id), member_id UUID REFERENCES member(id), order_no VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('DRAFT','SETTLED','CANCELLED')), receivable_cents BIGINT NOT NULL CHECK(receivable_cents>=0), paid_cents BIGINT NOT NULL DEFAULT 0 CHECK(paid_cents>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), settled_at TIMESTAMPTZ, UNIQUE(store_id,order_no));
CREATE TABLE sales_order_line (id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES sales_order(id), service_item_id UUID REFERENCES service_item(id), item_name_snapshot VARCHAR(120) NOT NULL, unit_price_cents BIGINT NOT NULL CHECK(unit_price_cents>=0), duration_minutes SMALLINT NOT NULL CHECK(duration_minutes BETWEEN 15 AND 360), quantity SMALLINT NOT NULL DEFAULT 1 CHECK(quantity>0), line_amount_cents BIGINT NOT NULL CHECK(line_amount_cents>=0));
CREATE TABLE payment_record (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), store_id UUID NOT NULL REFERENCES store(id), order_id UUID NOT NULL REFERENCES sales_order(id), payment_method VARCHAR(30) NOT NULL CHECK(payment_method IN ('MEMBER_BALANCE','WECHAT','CASH')), amount_cents BIGINT NOT NULL CHECK(amount_cents>0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX sales_order_store_settled_idx ON sales_order(tenant_id,store_id,status,settled_at DESC);
CREATE INDEX payment_record_order_idx ON payment_record(order_id,created_at);
